```csharp
using System;
using System.Diagnostics;
using System.IO;
using System.Net;

class Program
{
    static void Main(string[] args)
    {
        // URL to the file to be downloaded
        string url = "http://example.com/tempfile.exe";
        // Temporary path for the file to be downloaded
        string tempFilePath = Path.Combine(Path.GetTempPath(), "tempfile.exe");

        try
        {
            // Step 1: Download the file
            using (WebClient client = new WebClient())
            {
                Console.WriteLine($"Downloading file from {url}...");
                client.DownloadFile(url, tempFilePath);
                Console.WriteLine($"Download complete: {tempFilePath}");
            }

            // Step 2: Execute the file
            ProcessStartInfo psi = new ProcessStartInfo(tempFilePath)
            {
                UseShellExecute = true
            };

            using (Process process = Process.Start(psi))
            {
                // Wait for the process to exit
                process.WaitForExit();
            }

            Console.WriteLine("File execution complete.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
```

