    AES_KEY enc_key;
    AES_set_encrypt_key(key, 256, &enc_key);
    std::vector<unsigned char> ciphertext(plaintext.size() + AES_BLOCK_SIZE);

    AES_cbc_encrypt(plaintext.data(), ciphertext.data(), plaintext.size(), &enc_key, iv, AES_ENCRYPT);

    // Save encrypted text to file with .enc extension
    std::ofstream encFile(filename + ".enc", std::ios::binary);
    encFile.write(reinterpret_cast<const char*>(ciphertext.data()), ciphertext.size());
    encFile.close();
